package com.bank.loan.service;

import com.bank.loan.model.Interval;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds, for each interval, the index of the next qualifying interval.
public class NextIntervalService {
    private static final Logger log = Logger.getLogger(NextIntervalService.class.getName());

    public int[] findNextIntervals(List<Interval> intervals) {
        int n = intervals.size();
        int[] result = new int[n];
        Arrays.fill(result, -1);

        // Max-heaps carrying (value, originalIndex).
        PriorityQueue<int[]> startHeap =
                new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        PriorityQueue<int[]> endHeap =
                new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        for (int i = 0; i < n; i++) {
            startHeap.offer(new int[]{intervals.get(i).getStart(), i});
            endHeap.offer(new int[]{intervals.get(i).getEnd(), i});
        }

        while (!endHeap.isEmpty()) {
            int[] endTop = endHeap.poll();      // interval with the largest end
            int end = endTop[0];
            int endIndex = endTop[1];
            if (!startHeap.isEmpty() && startHeap.peek()[0] >= end) {
                int[] candidate = startHeap.poll();
                // Keep popping to find the SMALLEST start still >= end.
                while (!startHeap.isEmpty() && startHeap.peek()[0] >= end) {
                    candidate = startHeap.poll();
                }
                result[endIndex] = candidate[1];
                int ci = candidate[1];
                log.fine(() -> "Interval " + endIndex + " (end=" + end
                        + ") next = interval " + ci);
                // Re-offer: this start may still serve a smaller end later.
                startHeap.offer(candidate);
            }
        }
        log.info(() -> "Next-interval map = " + Arrays.toString(result));
        return result;
    }
}
