package com.bank.loan;

import com.bank.loan.model.Interval;
import com.bank.loan.service.NextIntervalService;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class NextIntervalApplication {
    private static final Logger log = Logger.getLogger(NextIntervalApplication.class.getName());

    public static void main(String[] args) {
        // Loan windows: 0:[2,3] 1:[3,4] 2:[5,6]
        List<Interval> loans = List.of(
                new Interval(2, 3), new Interval(3, 4), new Interval(5, 6));
        NextIntervalService service = new NextIntervalService();
        int[] next = service.findNextIntervals(loans);
        log.info("NBI loan next-window map: " + Arrays.toString(next));
    }
}
